"use client";
/* Bulb, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Bulb(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("bulb"); }, []);
  return React.createElement("piix-pal", { "pal": "bulb", ...piixAttrs(props) });
}

export default Bulb;
